head.script:
scwin.onpageload = function () {
    scwin.btn_search_onclick();
};

scwin.btn_insert_onclick = function (e) {
    var _rowIdx = userList.insertRow();
    userList.setCellData(_rowIdx, "tenantId", "1");
};

scwin.btn_delete_onclick = function (e) {
    var focusIdx = grd.getFocusedRowIndex();
    if (focusIdx < 0) {
        alert("삭제할 행을 먼저 선택해주세요.");
        return;
    }
    userList.deleteRow(focusIdx);
};

scwin.btn_remove_onclick = function (e) {
    var focusIdx = grd.getFocusedRowIndex();
    if (focusIdx < 0) {
        alert("삭제할 행을 먼저 선택해주세요.");
        return;
    }
    var removeData = userList.removeRow(focusIdx);
    console.log("삭제된 데이터:", JSON.stringify(removeData));
};

scwin.btn_deleteRows_onclick = function (e) {
    var chkIdxArr = grd.getCheckedIndex("chk");
    userList.deleteRows(chkIdxArr);
};

scwin.btn_removeRows_onclick = function (e) {
    var chkIdxArr = grd.getCheckedIndex("chk");
    let removeObjs = userList.removeRows(chkIdxArr);
    console.log(JSON.stringify(removeObjs));
};

scwin.btn_reset_onclick = function (e) {
    userList.setData([]);
};

scwin.btn_down_onclick = function (e) {
    var options = {
        exceptColumns: "chk"
    };
    grd.advancedExcelDownload({});
};

scwin.btn_upload_onclick = function (e) {
    var options = {};
    options.headerExist = "1";
    options.type = "1";
    options.status = "C";
    grd.advancedExcelUpload(options);
};

scwin.btn_search_onclick = function (e) {
    const urlParams = new URLSearchParams(window.location.search);
    const tenantIdFromUrl = "1"; // 또는 urlParams.get('tenant');

    var userDetailDataMap = $p.getComponentById("userDetail");

    if (userDetailDataMap) {
        userDetailDataMap.set("tenantId", tenantIdFromUrl);
    } else {
        alert("userDetail DataMap을 찾을 수 없습니다. XML의 ID를 확인해주세요.");
        return;
    }

    console.log("'sbm_selectUserList' 서브미션을 실행합니다. 전송 데이터:", userDetailDataMap.getJSON());
    $p.executeSubmission("sbm_selectUserList");
};

scwin.ui_schRole_onviewchange = function (info) {
    userList.clearFilter();
    userList.setColumnFilter({ type: 'row', colIndex: 'role', key: info.newValue, condition: 'and' });
};

scwin.sbm_selectTenantUser_submitdone = function (e) {
    var receivedData = e.responseJSON;

    if (Array.isArray(receivedData)) {
        userList.setJSON(receivedData);
    } else {
        var elHeader = receivedData.elHeader;
        if (elHeader && elHeader.resSuc === false) {
            $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        }
    }
};

scwin.sbm_saveAllUser_submitdone = function (e) {
    alert("저장이 완료되었습니다.");
    scwin.btn_search_onclick();
};

/**
 * @description 테넌트별 사용자 목록 조회 콜백 함수
 */
scwin.sbm_selectUserList_submitdone = function (e) {
    console.log("서버 응답 원본:", e.responseJSON);

    var responseData = e.responseJSON;

    var userArray = responseData.elData.userVoList;

    if (userArray && Array.isArray(userArray)) {
        userList.setJSON(userArray);

        scwin.maskAllPasswords();

    } else {
        userList.removeAll();
        console.error("서버 응답에서 유효한 사용자 목록 배열을 찾을 수 없습니다. 응답 구조를 확인하세요.");
    }

    console.log("DataList('userList')에 최종적으로 담긴 데이터:", userList.getAllJSON());
};

scwin.sbm_saveUserList_submitdone = function (e) {
    alert("저장이 완료되었습니다.");
    // 데이터 재조회하여 화면 갱신
    scwin.btn_search_onclick();
};

/**
 * @description 개선된 저장 버튼 클릭 이벤트
 */
scwin.btn_save_onclick = function (e) {
    console.log("저장 버튼 클릭됨");

    var dataList = $p.getComponentById("userList");
    if (!dataList) {
        console.error("userList DataList를 찾을 수 없습니다.");
        alert("데이터 목록을 찾을 수 없습니다.");
        return;
    }

    var modifiedData = dataList.getModifiedJSON();
    console.log("변경된 데이터:", modifiedData);

    if (modifiedData.length === 0) {
        alert("저장할 변경사항이 없습니다.");
        return;
    }

    if (confirm("변경 내용을 저장하시겠습니까?")) {
        // 저장 전 실제 비밀번호로 복원
        scwin.restorePasswordsBeforeSave();

        console.log("서버로 전송할 데이터:", dataList.getModifiedJSON());

        try {
            $p.executeSubmission("sbm_saveUserList");
            console.log("저장 서브미션 실행 완료");
        } catch (error) {
            console.error("저장 서브미션 실행 실패:", error);
            alert("저장 중 오류가 발생했습니다: " + error.message);
            scwin.reapplyPasswordMasking();
        }
    }
};

console.log("저장 버튼 함수 수정 완료!");

scwin.sbm_checkEmailByTenant_submitdone = function (e) {
    console.log("이메일 중복검사 완료:", e);

    try {
        var response = e.responseJSON;

        if (!response || !response.elData) {
            console.error("잘못된 서버 응답 형식입니다.", response);
            alert("서버 응답 처리 중 오류가 발생했습니다.");
            return;
        }

        var emailCheckResult = response.elData.emailCheckResult;
        var email = response.elData.email;

        if (emailCheckResult === "unavailable") {
            alert("'" + email + "'은(는) 이미 사용 중인 이메일입니다.\n다른 이메일을 입력해주세요.");

            if (scwin.currentEmailCheckRowIndex !== undefined) {
                var grid = $p.getComponentById("grd");
                var dataList = $p.getComponentById("userList");

                if (dataList.getRowStatus(scwin.currentEmailCheckRowIndex) === "C") {
                    dataList.setCellData(scwin.currentEmailCheckRowIndex, "email", "");
                }

                if (grid) {
                    grid.focusCell(scwin.currentEmailCheckRowIndex, "email");
                }
            }
        }
    } catch (error) {
        console.error("중복검사 결과 처리 중 오류:", error);
        alert("오류가 발생했습니다. 개발자 도구 콘솔을 확인해주세요.");
    }
};

scwin.grd_oncellindexchange = function (newRowIndex, newColIndex, oldRowIndex, oldColIndex) {
    console.log("=== oncellindexchange 이벤트 발생 ===");
    console.log("newRowIndex:", newRowIndex);
    console.log("newColIndex:", newColIndex);
    console.log("oldRowIndex:", oldRowIndex);
    console.log("oldColIndex:", oldColIndex);

    const grid = $p.getComponentById("grd");
    const oldColId = grid.getColumnID(oldColIndex);
    const newColId = grid.getColumnID(newColIndex);

    console.log("oldColId:", oldColId);
    console.log("newColId:", newColId);

    if (oldColId === "email") {
        console.log("이메일 컬럼에서 포커스가 이동했습니다.");

        // 이메일 값 가져오기
        const emailValue = userList.getCellData(oldRowIndex, "email");
        console.log("검사할 이메일 값:", emailValue);

        if (!emailValue || emailValue.trim() === "") {
            console.log("이메일이 비어있어 검사를 건너뜁니다.");
            return;
        }

        // 이메일 형식 검증
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(emailValue)) {
            alert("올바른 이메일 형식이 아닙니다.");
            // 포커스를 다시 이메일 셀로 이동
            setTimeout(function () {
                grid.focusCell(oldRowIndex, oldColIndex);
            }, 100);
            return;
        }

        // 중복검사 실행
        scwin.checkEmailDuplicate(emailValue, oldRowIndex);
    }
};

// 이메일 중복검사 함수
scwin.checkEmailDuplicate = function (email, rowIndex) {
    console.log("이메일 중복검사 시작:", email);

    $.ajax({
        url: '/InsWebApp/checkEmailByTenant.pwkjson',
        type: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({
            vo: {
                email: email,
                tenantId: "1"
            }
        }),
        success: function (response) {
            let emailCheckResult = response.emailCheckResult || response.elData?.emailCheckResult;

            if (emailCheckResult === "unavailable") {
                $c.win.alert("'" + email + "'은(는) 이미 사용 중인 이메일입니다.\n다른 이메일을 입력해주세요.", function () {
                    const grid = $p.getComponentById("grd");
                    if (grid && userList.getRowStatus(rowIndex) === "C") {
                        userList.setCellData(rowIndex, "email", "");
                        setTimeout(function () {
                            grid.focusCell(rowIndex, grid.getColumnIndex("email"));
                        }, 100);
                    }
                });
            } else if (emailCheckResult === "available") {
                console.log("사용 가능한 이메일입니다.");
            }
        },
        error: function (xhr, status, error) {
            $c.win.alert("이메일 중복검사 중 오류가 발생했습니다.");
        }
    });
};


/**
 * @description 모든 비밀번호를 *** 으로 마스킹
 */
scwin.maskAllPasswords = function () {
    var rowCount = userList.getTotalRow();
    for (var i = 0; i < rowCount; i++) {
        var password = userList.getCellData(i, "password");
        if (password && password.length > 0 && password !== "***") {
            userList.setCellData(i, "originalPassword", password);
            userList.setCellData(i, "password", "***");
        }
    }
};

/**
 * @description 그리드 셀 포커스 변경 시 처리
 */
scwin.grd_oncellposchange = function (row, col, oldRow, oldCol) {
    if (row === -1 || col === -1) return; // 유효하지 않은 인덱스 체크

    var grid = $p.getComponentById("grd");
    var colId = grid.getColumnID(col);
    var oldColId = oldCol >= 0 ? grid.getColumnID(oldCol) : null;

    console.log("셀 포커스 변경:", "새 위치(" + row + "," + colId + ") 이전 위치(" + oldRow + "," + oldColId + ")");

    if (colId === "password") {
        var currentValue = userList.getCellData(row, "password");
        var originalPassword = userList.getCellData(row, "originalPassword");

        console.log("비밀번호 컬럼 진입 - 현재값:", currentValue, "원본값:", originalPassword);

        if (currentValue === "***" && originalPassword) {
            userList.setCellData(row, "password", originalPassword);
            console.log("마스킹 해제 - 원본 비밀번호 표시");
        }
        else if (!currentValue || currentValue === "") {
            userList.setCellData(row, "password", "");
            console.log("새 행 - 빈 비밀번호");
        }
    }

    if (oldColId === "password" && oldRow >= 0) {
        var currentPassword = userList.getCellData(oldRow, "password");

        console.log("비밀번호 컬럼 이탈 - 현재값:", currentPassword);

        if (currentPassword && currentPassword !== "***" && currentPassword.trim() !== "") {
            userList.setCellData(oldRow, "originalPassword", currentPassword);
            userList.setCellData(oldRow, "password", "***");
            console.log("비밀번호 마스킹 처리 완료");
        }
    }
};

/**
 * @description 셀 편집 완료 시 처리 (추가 보완)
 */
scwin.grd_oncelleditend = function (row, col, value) {
    var grid = $p.getComponentById("grd");
    var colId = grid.getColumnID(col);

    console.log("셀 편집 완료:", colId, "값:", value);

    if (colId === "password") {
        if (value && value !== "***" && value.trim() !== "") {
            userList.setCellData(row, "originalPassword", value);

            setTimeout(function () {
                var currentValue = userList.getCellData(row, "password");
                if (currentValue !== "***") {
                    userList.setCellData(row, "password", "***");
                    console.log("편집 완료 후 마스킹 적용");
                }
            }, 500); 
        }
    }
};


/**
 * @description 저장 전 실제 비밀번호로 복원
 */
scwin.restorePasswordsBeforeSave = function () {
    console.log("저장 전 비밀번호 복원 시작");
    var rowCount = userList.getTotalRow();
    var restoredCount = 0;

    for (var i = 0; i < rowCount; i++) {
        var originalPassword = userList.getCellData(i, "originalPassword");
        var currentPassword = userList.getCellData(i, "password");

        if (originalPassword && currentPassword === "***") {
            userList.setCellData(i, "password", originalPassword);
            restoredCount++;
            console.log("행 " + i + " 비밀번호 복원");
        }
    }

    console.log("총 " + restoredCount + "개 비밀번호 복원 완료");
};

/**
 * @description 저장 후 다시 마스킹 적용
 */
scwin.reapplyPasswordMasking = function () {
    console.log("저장 후 비밀번호 재마스킹 시작");
    setTimeout(function () {
        scwin.maskAllPasswords();
        console.log("비밀번호 재마스킹 완료");
    }, 100);
};
